mapper.select:
select 
from spot_reservation_slot
where spot_id = #{spotId}
  and visit_date = #{visitDate}
  and start_time = #{startTime}
  and end_time = #{endTime}
limit 1

select 
from spot_reservation_slot
where 1 = 1
and scenic_area_id = #{scenicAreaId}
and spot_id = #{spotId}
and visit_date = #{visitDate}
and visit_date >= #{startDate}
and visit_date <= #{endDate}
and status = #{status}
order by visit_date desc, start_time asc, id desc

select 
from spot_reservation_slot
where spot_id = #{spotId}
  and visit_date = #{visitDate}
order by start_time asc, id asc

mapper.insert:
insert into spot_reservation_slot (
    scenic_area_id, spot_id, rule_id, visit_date, start_time, end_time,
    total_capacity, reserved_count, status, remark, create_by, create_time, update_by, update_time
) values (
    #{scenicAreaId}, #{spotId}, #{ruleId}, #{visitDate}, #{startTime}, #{endTime},
    #{totalCapacity}, #{reservedCount}, #{status}, #{remark}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}
)

mapper.update:
update spot_reservation_slot
total_capacity = #{totalCapacity}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}

update spot_reservation_slot
set reserved_count = reserved_count - #{visitorCount},
    update_time = now()
where id = #{id}
  and reserved_count >= #{visitorCount}
